        n=sum(len(s)==p+1 for s in K)
        rp=rank_mod2(boundary_matrix(K,p)) if p else 0
        rn=rank_mod2(boundary_matrix(K,p+1))
        out.append(n-rp-rn)
    return tuple(out)

