filled_triangle = close_under_faces([(0, 1, 2)])
square_loop = close_under_faces([(0, 1), (1, 2), (2, 3), (0, 3)])
house = close_under_faces([('A','B','E'), ('B','C'), ('C','D'), ('D','E')])
hollow_tetrahedron = close_under_faces([(0, 1, 2), (0, 1, 3),
